import {Link} from '@github-ui/react-core/link'
import {CodeOfConductIcon} from '@primer/octicons-react'
import {Button} from '@primer/react'
import {clsx} from 'clsx'

import styles from './CodeOfConductSelector.module.css'

export default function CodeOfConductSelector({url, className}: {url: string; className?: string}) {
  return (
    <Button
      variant="invisible"
      as={Link}
      to={url}
      leadingVisual={CodeOfConductIcon}
      className={clsx(styles.Button, className)}
    >
      Choose a code of conduct template
    </Button>
  )
}

try{ CodeOfConductSelector.displayName ||= 'CodeOfConductSelector' } catch {}